import{_ as t,o as s,c as n,a2 as e}from"./chunks/framework.CRFziyHp.js";const c=JSON.parse('{"title":"快速上手","description":"","frontmatter":{},"headers":[],"relativePath":"features/ui-editor/getting-started.md","filePath":"features/ui-editor/getting-started.md","lastUpdated":1785013113000}'),r={name:"features/ui-editor/getting-started.md"};function i(l,a,o,p,h,d){return s(),n("div",null,[...a[0]||(a[0]=[e(`<h1 id="快速上手" tabindex="-1">快速上手 <a class="header-anchor" href="#快速上手" aria-label="Permalink to &quot;快速上手&quot;">​</a></h1><p>本篇带您完成 <strong>第一次页面设计</strong>：从进入编辑器到客户端看到效果。</p><h2 id="第一步-进入页面配置" tabindex="-1">第一步：进入页面配置 <a class="header-anchor" href="#第一步-进入页面配置" aria-label="Permalink to &quot;第一步：进入页面配置&quot;">​</a></h2><ol><li>浏览器打开管理后台（见 <a href="/guide/admin-access">进入管理后台</a>）</li><li>左侧菜单 → <strong>UI管理 → 页面配置</strong></li><li>顶部 <strong>区域</strong> 筛选：首次建议选 <strong>平台默认</strong>，作为全站兜底</li></ol><h2 id="第二步-新建或编辑页面" tabindex="-1">第二步：新建或编辑页面 <a class="header-anchor" href="#第二步-新建或编辑页面" aria-label="Permalink to &quot;第二步：新建或编辑页面&quot;">​</a></h2><h3 id="新建" tabindex="-1">新建 <a class="header-anchor" href="#新建" aria-label="Permalink to &quot;新建&quot;">​</a></h3><ol><li>点击右上角 <strong>+ 新建页面</strong></li><li>选择页面类型（见 <a href="/features/ui-editor/page-types">页面类型说明</a>）</li><li>填写页面名称</li><li>点击 <strong>创建并编辑</strong>（面板类页面为 <strong>进入配置</strong>）</li></ol><h3 id="编辑已有页面" tabindex="-1">编辑已有页面 <a class="header-anchor" href="#编辑已有页面" aria-label="Permalink to &quot;编辑已有页面&quot;">​</a></h3><p>在卡片上点击 <strong>设计</strong>（面板类为 <strong>配置</strong>）。</p><p>左侧可按类型筛选：应用首页、功能页面、自定义页面、社区圈子等。</p><h2 id="第三步-添加组件" tabindex="-1">第三步：添加组件 <a class="header-anchor" href="#第三步-添加组件" aria-label="Permalink to &quot;第三步：添加组件&quot;">​</a></h2><ol><li>在 <strong>左侧组件库</strong> 展开分类，点击某个组件（如「轮播图」）</li><li>组件会插入 <strong>中间手机画布</strong>，并自动选中</li><li>在 <strong>右侧属性面板</strong> 修改内容（如上传轮播图片）</li><li>切换到 <strong>样式</strong> Tab 调整间距、圆角等</li></ol><h3 id="调整顺序" tabindex="-1">调整顺序 <a class="header-anchor" href="#调整顺序" aria-label="Permalink to &quot;调整顺序&quot;">​</a></h3><ul><li>选中组件后，使用节点操作菜单 <strong>上移 / 下移 / 复制 / 删除</strong></li><li>列表类组件（笔记列表等）建议放在页面 <strong>靠下位置</strong></li></ul><h3 id="推荐首页结构" tabindex="-1">推荐首页结构 <a class="header-anchor" href="#推荐首页结构" aria-label="Permalink to &quot;推荐首页结构&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>轮播图 / 顶部图</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>金刚区 / 搜索栏</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>筛选标签（可选，与下方列表联动）</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>话题气泡 / 榜单 / 双卡行动 等运营模块</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>笔记列表 或 圈子列表 或 瀑布流（三选一）</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>结束文本（可选，作为列表页脚）</span></span></code></pre></div><h2 id="第四步-配置页面级设置" tabindex="-1">第四步：配置页面级设置 <a class="header-anchor" href="#第四步-配置页面级设置" aria-label="Permalink to &quot;第四步：配置页面级设置&quot;">​</a></h2><p>在画布上 <strong>点击空白处</strong>（不选中任何组件），右侧显示 <strong>页面配置</strong>：</p><ul><li>页面背景色、顶部背景图</li><li>导航栏标题、样式（默认 / 胶囊 / 自定义 / 隐藏）</li><li>分享标题与封面（部分页面）</li></ul><p>详见 <a href="/features/ui-editor/interface#页面级配置">编辑器界面说明</a>。</p><h2 id="第五步-保存" tabindex="-1">第五步：保存 <a class="header-anchor" href="#第五步-保存" aria-label="Permalink to &quot;第五步：保存&quot;">​</a></h2><p>工具栏点击 <strong>保存</strong>：</p><ul><li>可选择是否 <strong>同时更新封面截图</strong>（用于页面列表缩略图）</li><li>保存后写入服务器，但 <strong>尚未对用户生效</strong></li></ul><h2 id="第六步-启用-发布" tabindex="-1">第六步：启用（发布） <a class="header-anchor" href="#第六步-启用-发布" aria-label="Permalink to &quot;第六步：启用（发布）&quot;">​</a></h2><p>返回 <strong>页面配置列表</strong>：</p><ol><li>找到刚保存的页面卡片</li><li>若状态为 <strong>禁用</strong>，点击 <strong>启用</strong></li><li>同区域、同页面类型下，其它版本会自动变为禁用</li></ol><div class="warning custom-block"><p class="custom-block-title">必须启用</p><p>仅「保存」不会切换线上版本；用户端拉取的是 <strong>启用中</strong> 的那一条配置。</p></div><h2 id="第七步-客户端验证" tabindex="-1">第七步：客户端验证 <a class="header-anchor" href="#第七步-客户端验证" aria-label="Permalink to &quot;第七步：客户端验证&quot;">​</a></h2><ol><li>确认客户端当前 <strong>区域</strong> 与编辑区域一致</li><li>杀进程重进 App，或在首页 <strong>下拉刷新</strong></li><li>检查修改的模块是否已更新</li></ol><p>Tab 页（首页、发现）有本地缓存，若未更新可稍等或清除缓存。</p><h2 id="配置-tabbar-可选" tabindex="-1">配置 TabBar（可选） <a class="header-anchor" href="#配置-tabbar-可选" aria-label="Permalink to &quot;配置 TabBar（可选）&quot;">​</a></h2><p>底部导航在独立页面配置：</p><p><strong>UI管理 → TabBar配置</strong> → 选择区域 → 编辑 Tab 项 → <strong>保存配置</strong></p><p>详见 <a href="/features/ui-editor/tabbar">TabBar 配置</a>。</p><h2 id="多区域复制技巧" tabindex="-1">多区域复制技巧 <a class="header-anchor" href="#多区域复制技巧" aria-label="Permalink to &quot;多区域复制技巧&quot;">​</a></h2><ol><li>先在 <strong>平台默认</strong> 做好一套完整 UI</li><li>切换到目标区域 → <strong>新建页面</strong> 选同类型</li><li>或在列表对已有配置 <strong>复制</strong>，再微调</li><li>启用该区域版本</li></ol><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><a href="/features/ui-editor/interface">编辑器界面说明</a> — 撤销、预览、导入导出</li><li><a href="/features/ui-editor/styles-and-actions">样式与点击动作</a></li><li><a href="/features/ui-editor/components-basic">组件手册</a></li></ul>`,38)])])}const u=t(r,[["render",i]]);export{c as __pageData,u as default};
